    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RB_0LC0LD_1LA1RD [SWinR 2] (StC, S1) ltac:(vm_compute; reflexivity)
