Lemma fire_1RB1LD_1RC0RB_1LA0RC_0LD0RC : forall t, ~ In t pins_1RB1LD_1RC0RB_1LA0RC_0LD0RC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
