    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RB_1LA0RC_0LD0RC [SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
