    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB1LD_1RC0RB_1LA0RC_0LD0RC [SWinR 4; SCycL 2 0; SWin 1; SWinL 3; SCycR 2; SWin 3] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

