(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB1LD_1RC0RB_1LA1RB_0LD1RC : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Dp q0 ++ [S0]) [] j A0_1RB1LD_1RC0RB_1LA1RB_0LD1RC.
Proof.
  intros p j q0 E. destruct (DpCounter.cview_some_D p j q0 E) as (H1 & _).
  unfold Cc_1RB1LD_1RC0RB_1LA1RB_0LD1RC, cden, A0_1RB1LD_1RC0RB_1LA1RB_0LD1RC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  rewrite H1. first [ rewrite <- (app_assoc (rep [S1;S1] j)); reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gei_1RB1LD_1RC0RB_1LA1RB_0LD1RC : forall p j q0, cview p = (j, Some q0) ->
  cden (Dp q0 ++ [S0]) [] j A1_1RB1LD_1RC0RB_1LA1RB_0LD1RC = Cc (Pos.succ p).
Proof.
