(** ** The lap *)

Lemma lap_1RB1LD_1RC0RB_1LA1RB_0LD1RC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
