  - destruct (lapi_1RB1LD_1RC0RB_1LA1RB_0LD1RC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB1LD_1RC0RB_1LA1RB_0LD1RC B0_1RB1LD_1RC0RB_1LA1RB_0LD1RC B1_1RB1LD_1RC0RB_1LA1RB_0LD1RC 4 14 p j' [] []).
    + exact run_ovf_1RB1LD_1RC0RB_1LA1RB_0LD1RC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB1LD_1RC0RB_1LA1RB_0LD1RC p j' E).
    + exact (geo_1RB1LD_1RC0RB_1LA1RB_0LD1RC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LD_1RC0RB_1LA1RB_0LD1RC : stepn tmm_1RB1LD_1RC0RB_1LA1RB_0LD1RC 12 InitES = Some (lift (Cc 1)).
