      with (l := [SWin 4; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB1LD_1RC0RB_1LA1RD_0LD0RC
      with (l := [SWin 4; SCycL 2 0; SWin 1]).
