  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB1LD_1RC0RB_1LA1RD_0LD0RC
      with (l := [SWin 4; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
  - (* D1 *)
