  - intros t Ht p _. apply fire_1RB1LD_1RC0RB_1LA1RD_0LD0RC. exact Ht.
  - exact wit_1RB1LD_1RC0RB_1LA1RD_0LD0RC.
  - apply qcleb_QC_26. reflexivity.
